    33  /** @brief Table of direction-to-face mapping for each pentagon
    34   *
    35   * Note that faces are in directional order, starting at J_AXES_DIGIT.
    36   * This table is generated by the generatePentagonDirectionFaces script.
    37   */
    38  static const PentagonDirectionFaces pentagonDirectionFaces[NUM_PENTAGONS] = {
    39      {4, {4, 0, 2, 1, 3}},       {14, {6, 11, 2, 7, 1}},
    40      {24, {5, 10, 1, 6, 0}},     {38, {7, 12, 3, 8, 2}},
    41      {49, {9, 14, 0, 5, 4}},     {58, {8, 13, 4, 9, 3}},
    42      {63, {11, 6, 15, 10, 16}},  {72, {12, 7, 16, 11, 17}},
    43      {83, {10, 5, 19, 14, 15}},  {97, {13, 8, 17, 12, 18}},
    44      {107, {14, 9, 18, 13, 19}}, {117, {15, 19, 17, 18, 16}},
    45  };
    46
    47  /**
    48   * Get the number of CCW rotations of the cell's vertex numbers
    49   * compared to the directional layout of its neighbors.
    50   * @param out Number of CCW rotations for the cell
    51   */
    52  static H3Error vertexRotations(H3Index cell, int *out) {
    53      // Get the face and other info for the origin
    54      FaceIJK fijk;
    55      H3Error err = _h3ToFaceIjk(cell, &fijk);
    56      if (err) {
    57          return err;
    58      }
    59      int baseCell = H3_EXPORT(getBaseCellNumber)(cell);
    60      int cellLeadingDigit = _h3LeadingNonZeroDigit(cell);
    61
    62      // get the base cell face
    63      FaceIJK baseFijk;
    64      _baseCellToFaceIjk(baseCell, &baseFijk);
    65
    66      int ccwRot60 = _baseCellToCCWrot60(baseCell, fijk.face);
    67
    68      if (_isBaseCellPentagon(baseCell)) {
    69          // Find the appropriate direction-to-face mapping
    70          PentagonDirectionFaces dirFaces;
    71          // Excluding from branch coverage as we never hit the end condition
    72          for (int p = 0; p < NUM_PENTAGONS; p++) {  // LCOV_EXCL_BR_LINE
    73              if (pentagonDirectionFaces[p].baseCell == baseCell) {
    74                  dirFaces = pentagonDirectionFaces[p];
    75                  break;
    76              }
    77          }
    78
    79          // additional CCW rotation for polar neighbors or IK neighbors
    80          if (fijk.face != baseFijk.face &&
    81              (_isBaseCellPolarPentagon(baseCell) ||
    82               fijk.face ==
    83                   dirFaces.faces[IK_AXES_DIGIT - DIRECTION_INDEX_OFFSET])) {
    84              ccwRot60 = (ccwRot60 + 1) % 6;
    85          }
    86
    87          // Check whether the cell crosses a deleted pentagon subsequence
    88          if (cellLeadingDigit == JK_AXES_DIGIT &&
    89              fijk.face ==
    90                  dirFaces.faces[IK_AXES_DIGIT - DIRECTION_INDEX_OFFSET]) {
    91              // Crosses from JK to IK: Rotate CW
    92              ccwRot60 = (ccwRot60 + 5) % 6;
    93          } else if (cellLeadingDigit == IK_AXES_DIGIT &&
    94                     fijk.face ==
    95                         dirFaces.faces[JK_AXES_DIGIT - DIRECTION_INDEX_OFFSET]) {
    96              // Crosses from IK to JK: Rotate CCW
    97              ccwRot60 = (ccwRot60 + 1) % 6;
    98          }
    99      }
   100      *out = ccwRot60;
   101      return E_SUCCESS;
   102  }
