   104  /** @brief Hexagon direction to vertex number relationships (same face).
   105   *         Note that we don't use direction 0 (center).
   106   */
   107  static const int directionToVertexNumHex[NUM_DIGITS] = {
   108      INVALID_DIGIT, 3, 1, 2, 5, 4, 0};
   109
   110  /** @brief Pentagon direction to vertex number relationships (same face).
   111   *         Note that we don't use directions 0 (center) or 1 (deleted K axis).
   112   */
   113  static const int directionToVertexNumPent[NUM_DIGITS] = {
   114      INVALID_DIGIT, INVALID_DIGIT, 1, 2, 4, 3, 0};
   115
   116  /**
   117   * Get the first vertex number for a given direction. The neighbor in this
   118   * direction is located between this vertex number and the next number in
   119   * sequence.
   120   * @returns The number for the first topological vertex, or INVALID_VERTEX_NUM
   121   *          if the direction is not valid for this cell
   122   */
   123  int vertexNumForDirection(const H3Index origin, const Direction direction) {
   124      int isPent = H3_EXPORT(isPentagon)(origin);
   125      // Check for invalid directions
   126      if (direction == CENTER_DIGIT || direction >= INVALID_DIGIT ||
   127          (isPent && direction == K_AXES_DIGIT))
   128          return INVALID_VERTEX_NUM;
   129
   130      // Determine the vertex rotations for this cell
   131      int rotations;
   132      H3Error err = vertexRotations(origin, &rotations);
   133      if (err) {
   134          return INVALID_VERTEX_NUM;
   135      }
   136
   137      // Find the appropriate vertex, rotating CCW if necessary
   138      if (isPent) {
   139          return (directionToVertexNumPent[direction] + NUM_PENT_VERTS -
   140                  rotations) %
   141                 NUM_PENT_VERTS;
   142      } else {
   143          return (directionToVertexNumHex[direction] + NUM_HEX_VERTS -
   144                  rotations) %
   145                 NUM_HEX_VERTS;
   146      }
   147  }
   148
   149  /** @brief Vertex number to hexagon direction relationships (same face).
   150   */
   151  static const Direction vertexNumToDirectionHex[NUM_HEX_VERTS] = {
   152      IJ_AXES_DIGIT, J_AXES_DIGIT,  JK_AXES_DIGIT,
   153      K_AXES_DIGIT,  IK_AXES_DIGIT, I_AXES_DIGIT};
   154
   155  /** @brief Vertex number to pentagon direction relationships (same face).
   156   */
   157  static const Direction vertexNumToDirectionPent[NUM_PENT_VERTS] = {
   158      IJ_AXES_DIGIT, J_AXES_DIGIT, JK_AXES_DIGIT, IK_AXES_DIGIT, I_AXES_DIGIT};
   159
   160  /**
   161   * Get the direction for a given vertex number. This returns the direction for
   162   * the neighbor between the given vertex number and the next number in sequence.
   163   * @returns The direction for this vertex, or INVALID_DIGIT if the vertex
   164   * number is invalid.
   165   */
   166  Direction directionForVertexNum(const H3Index origin, const int vertexNum) {
   167      int isPent = H3_EXPORT(isPentagon)(origin);
   168      // Check for invalid vertexes
   169      if (vertexNum < 0 ||
   170          vertexNum > (isPent ? NUM_PENT_VERTS : NUM_HEX_VERTS) - 1)
   171          return INVALID_DIGIT;
   172
   173      // Determine the vertex rotations for this cell
   174      int rotations;
   175      H3Error err = vertexRotations(origin, &rotations);
   176      if (err) {
   177          return INVALID_DIGIT;
   178      }
   179
   180      // Find the appropriate direction, rotating CW if necessary
   181      return isPent ? vertexNumToDirectionPent[(vertexNum + rotations) %
   182                                               NUM_PENT_VERTS]
   183                    : vertexNumToDirectionHex[(vertexNum + rotations) %
   184                                              NUM_HEX_VERTS];
   185  }
   186
   187  /** @brief Directions in CCW order */
   188  static const Direction DIRECTIONS[NUM_HEX_VERTS] = {
   189      J_AXES_DIGIT,  JK_AXES_DIGIT, K_AXES_DIGIT,
   190      IK_AXES_DIGIT, I_AXES_DIGIT,  IJ_AXES_DIGIT};
   191
   192  /** @brief Reverse direction from neighbor in each direction,
   193   *         given as an index into DIRECTIONS to facilitate rotation
   194   */
   195  static const int revNeighborDirectionsHex[NUM_DIGITS] = {
   196      INVALID_DIGIT, 5, 3, 4, 1, 0, 2};
   197
   198  /**
   199   * Get a single vertex for a given cell, as an H3 index, or
   200   * H3_NULL if the vertex is invalid
   201   * @param cell    Cell to get the vertex for
   202   * @param vertexNum Number (index) of the vertex to calculate
   203   */
   204  H3Error H3_EXPORT(cellToVertex)(H3Index cell, int vertexNum, H3Index *out) {
   205      int cellIsPentagon = H3_EXPORT(isPentagon)(cell);
   206      int cellNumVerts = cellIsPentagon ? NUM_PENT_VERTS : NUM_HEX_VERTS;
   207      int res = H3_GET_RESOLUTION(cell);
   208
   209      // Check for invalid vertexes
   210      if (vertexNum < 0 || vertexNum > cellNumVerts - 1) return E_DOMAIN;
   211
   212      // Default the owner and vertex number to the input cell
   213      H3Index owner = cell;
   214      int ownerVertexNum = vertexNum;
   215
   216      // Determine the owner, looking at the three cells that share the vertex.
   217      // By convention, the owner is the cell with the lowest numerical index.
   218
   219      // If the cell is the center child of its parent, it will always have
   220      // the lowest index of any neighbor, so we can skip determining the owner
   221      if (res == 0 || H3_GET_INDEX_DIGIT(cell, res) != CENTER_DIGIT) {
   222          // Get the left neighbor of the vertex, with its rotations
   223          Direction left = directionForVertexNum(cell, vertexNum);
   224          if (left == INVALID_DIGIT) return E_FAILED;
   225          int lRotations = 0;
   226          H3Index leftNeighbor;
   227          h3NeighborRotations(cell, left, &lRotations, &leftNeighbor);
   228          // Set to owner if lowest index
   229          if (leftNeighbor < owner) owner = leftNeighbor;
   230
   231          // As above, skip the right neighbor if the left is known lowest
   232          if (res == 0 || H3_GET_INDEX_DIGIT(leftNeighbor, res) != CENTER_DIGIT) {
   233              // Get the right neighbor of the vertex, with its rotations
   234              // Note that vertex - 1 is the right side, as vertex numbers are CCW
   235              Direction right = directionForVertexNum(
   236                  cell, (vertexNum - 1 + cellNumVerts) % cellNumVerts);
   237              // This case should be unreachable; invalid verts fail earlier
   238              if (right == INVALID_DIGIT) return E_FAILED;  // LCOV_EXCL_LINE
   239              int rRotations = 0;
   240              H3Index rightNeighbor;
   241              h3NeighborRotations(cell, right, &rRotations, &rightNeighbor);
   242              // Set to owner if lowest index
   243              if (rightNeighbor < owner) {
   244                  owner = rightNeighbor;
   245                  Direction dir =
   246                      H3_EXPORT(isPentagon)(owner)
   247                          ? directionForNeighbor(owner, cell)
   248                          : DIRECTIONS[(revNeighborDirectionsHex[right] +
   249                                        rRotations) %
   250                                       NUM_HEX_VERTS];
   251                  ownerVertexNum = vertexNumForDirection(owner, dir);
   252              }
   253          }
   254
   255          // Determine the vertex number for the left neighbor
   256          if (owner == leftNeighbor) {
   257              int ownerIsPentagon = H3_EXPORT(isPentagon)(owner);
   258              Direction dir =
   259                  ownerIsPentagon
   260                      ? directionForNeighbor(owner, cell)
   261                      : DIRECTIONS[(revNeighborDirectionsHex[left] + lRotations) %
   262                                   NUM_HEX_VERTS];
   263
   264              // For the left neighbor, we need the second vertex of the
   265              // edge, which may involve looping around the vertex nums
   266              ownerVertexNum = vertexNumForDirection(owner, dir) + 1;
   267              if (ownerVertexNum == NUM_HEX_VERTS ||
   268                  (ownerIsPentagon && ownerVertexNum == NUM_PENT_VERTS)) {
   269                  ownerVertexNum = 0;
   270              }
   271          }
   272      }
   273
   274      // Create the vertex index
   275      H3Index vertex = owner;
   276      H3_SET_MODE(vertex, H3_VERTEX_MODE);
   277      H3_SET_RESERVED_BITS(vertex, ownerVertexNum);
   278      *out = vertex;
   279
   280      return E_SUCCESS;
   281  }
