   283  /**
   284   * Get all vertexes for the given cell
   285   * @param cell      Cell to get the vertexes for
   286   * @param vertexes  Array to hold vertex output. Must have length >= 6.
   287   */
   288  H3Error H3_EXPORT(cellToVertexes)(H3Index cell, H3Index *vertexes) {
   289      // Get all vertexes. If the cell is a pentagon, will fill the final slot
   290      // with H3_NULL.
   291      bool isPent = H3_EXPORT(isPentagon)(cell);
   292      for (int i = 0; i < NUM_HEX_VERTS; i++) {
   293          if (i == 5 && isPent) {
   294              vertexes[i] = H3_NULL;
   295          } else {
   296              H3Error cellError = H3_EXPORT(cellToVertex)(cell, i, &vertexes[i]);
   297              if (cellError) {
   298                  return cellError;
   299              }
   300          }
   301      }
   302      return E_SUCCESS;
   303  }
