   305  /**
   306   * Get the geocoordinates of an H3 vertex
   307   * @param vertex H3 index describing a vertex
   308   * @param coord  Output geo coordinate
   309   */
   310  H3Error H3_EXPORT(vertexToLatLng)(H3Index vertex, LatLng *coord) {
   311      // Get the vertex number and owner from the vertex
   312      int vertexNum = H3_GET_RESERVED_BITS(vertex);
   313      H3Index owner = vertex;
   314      H3_SET_MODE(owner, H3_CELL_MODE);
   315      H3_SET_RESERVED_BITS(owner, 0);
   316
   317      // Get the single vertex from the boundary
   318      CellBoundary gb;
   319      FaceIJK fijk;
   320      H3Error fijkError = _h3ToFaceIjk(owner, &fijk);
   321      if (fijkError) {
   322          return fijkError;
   323      }
   324      int res = H3_GET_RESOLUTION(owner);
   325
   326      if (H3_EXPORT(isPentagon)(owner)) {
   327          _faceIjkPentToCellBoundary(&fijk, res, vertexNum, 1, &gb);
   328      } else {
   329          _faceIjkToCellBoundary(&fijk, res, vertexNum, 1, &gb);
   330      }
   331
   332      // Copy from boundary to output coord
   333      *coord = gb.verts[0];
   334      return E_SUCCESS;
   335  }
