   337  /**
   338   * Whether the input is a valid H3 vertex
   339   * @param  vertex H3 index possibly describing a vertex
   340   * @return        Whether the input is valid
   341   */
   342  int H3_EXPORT(isValidVertex)(H3Index vertex) {
   343      if (H3_GET_MODE(vertex) != H3_VERTEX_MODE) {
   344          return 0;
   345      }
   346
   347      int vertexNum = H3_GET_RESERVED_BITS(vertex);
   348      H3Index owner = vertex;
   349      H3_SET_MODE(owner, H3_CELL_MODE);
   350      H3_SET_RESERVED_BITS(owner, 0);
   351
   352      if (!H3_EXPORT(isValidCell)(owner)) {
   353          return 0;
   354      }
   355
   356      // The easiest way to ensure that the owner + vertex number is valid,
   357      // and that the vertex is canonical, is to recreate and compare.
   358      H3Index canonical;
   359      if (H3_EXPORT(cellToVertex)(owner, vertexNum, &canonical)) {
   360          return 0;
   361      }
   362
   363      return vertex == canonical ? 1 : 0;
   364  }
